import{_ as a,o,c as s,a4 as t}from"./chunks/framework.DA9C4Pbl.js";const k=JSON.parse('{"title":"Updates of Arcsecond.local","description":"","frontmatter":{"title":"Updates of Arcsecond.local","visibility":"public","audience":"operator","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/operating/updates.md","filePath":"guides/operating/updates.md"}'),i={name:"guides/operating/updates.md"};function n(r,e,d,l,c,h){return o(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="updates-of-arcsecond-local" tabindex="-1">Updates of Arcsecond.local <a class="header-anchor" href="#updates-of-arcsecond-local" aria-label="Permalink to “Updates of Arcsecond.local”">​</a></h1><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>As of now, the installation of Arcsecond.local requires an individual authentication token, provided manually by Arcsecond. In the future, the process will be streamlined and easier.</p></div><p>Your installation can keep running while it updates: there is no need to stop it first. Two commands, from any folder once <code>arcsecond setup</code> has run on this machine:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arcsecond</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>The first updates the <code>arcsecond</code> tool itself. The second updates the installation: it brings <code>docker-compose.yml</code> up to date (see below), downloads the latest images, recreates the containers whose image changed, waits for the backend to be ready again, and prints the address. Expect a minute or two while the containers come back; the tool waits for you.</p><p><code>arcsecond status</code> says whether an installation is current: it compares the version of your <code>docker-compose.yml</code> with the one the installed tool carries, and tells you to run <code>arcsecond update</code> when they differ.</p><h2 id="why-the-compose-file-is-refreshed" tabindex="-1">Why the compose file is refreshed <a class="header-anchor" href="#why-the-compose-file-is-refreshed" aria-label="Permalink to “Why the compose file is refreshed”">​</a></h2><p>The <code>docker-compose.yml</code> file is not part of the Docker images: it is written by the <code>arcsecond</code> tool, and evolves with it — which is why the tool is updated first. The file belongs to the tool: <code>arcsecond update</code> always leaves it exactly as the installed tool writes it. When the file differed — an older template, or an edit by hand — the previous one is kept beside it as <code>docker-compose.backup-&lt;date&gt;-&lt;time&gt;.yml</code>, so nothing is lost. Your <code>.env</code> file only gains keys it lacks, and your data is never touched.</p><p>Changes of your own that must survive updates go in a <code>docker-compose.override.yml</code> beside it: compose applies that file on top of <code>docker-compose.yml</code>, every <code>arcsecond</code> command passes it along, and the tool never touches it.</p><p>The latest change of this kind: since CLI 3.20.0 (template version 6.4), the database and Redis containers no longer publish a port on the machine, not even on <code>localhost</code>. They are reachable from the other containers only, which is all Arcsecond ever needed, and an installation can now start next to a PostgreSQL already running on the machine. An installation that fails with <em>ports are not available</em> on <code>arcsecond start</code> is one that has not had this update; see <a href="/guides/operating/troubleshooting">Troubleshooting</a>.</p><h2 id="coming-from-a-tool-older-than-4-5" tabindex="-1">Coming from a tool older than 4.5 <a class="header-anchor" href="#coming-from-a-tool-older-than-4-5" aria-label="Permalink to “Coming from a tool older than 4.5”">​</a></h2><p>Since version 4.5 of the tool, the weather forecast uses <strong>your own Tomorrow.io API key</strong>. Arcsecond&#39;s own key was never shipped with Arcsecond.local, so an installation without a key has had no forecast. <code>arcsecond update</code> adds an empty <code>TOMORROW_IO_API_KEY</code> line to <code>.env</code> but does not ask for the key. Get a free key from <a href="https://www.tomorrow.io/weather-api/" target="_blank" rel="noreferrer">tomorrow.io</a>, then:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tomorrow-io-key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div><p><code>arcsecond doctor</code> says whether a key is set. See <a href="/reference/compose/environment#tomorrow-io-api-key">Environment</a>. The key works with the images you already have. Until <code>arcsecond update</code> brings a backend image newer than 4.5, the installation asks Tomorrow.io every five minutes per site instead of hourly, and a free key then covers a single observing site.</p><h2 id="coming-from-a-tool-older-than-4-0" tabindex="-1">Coming from a tool older than 4.0 <a class="header-anchor" href="#coming-from-a-tool-older-than-4-0" aria-label="Permalink to “Coming from a tool older than 4.0”">​</a></h2><p>Version 4.0 of the tool changed how an installation is operated — <code>arcsecond start</code> and friends replace the <code>docker compose</code> commands these pages used to ask for. The installation itself needs no change. See <a href="/guides/operating/upgrading-to-4">Upgrading to 4.0</a>.</p>`,16)])])}const g=a(i,[["render",n]]);export{k as __pageData,g as default};
